  }
}

'use strict';

module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  roots: ['<rootDir>/tests'],
  testMatch: ['**/*.test.ts'],
  transform: {
    '^.+\\.ts$': ['ts-jest', { tsconfig: 'tsconfig.test.json' }],
  },
  collectCoverageFrom: ['src/**/*.ts'],
  coverageDirectory: 'coverage',
};

import matter from 'gray-matter';
import { marked } from 'marked';

export interface Frontmatter {
  [key: string]: unknown;
}

export interface ParsedDocument {
  frontmatter: Frontmatter;
  html: string;
  body: string;
}

const FRONTMATTER_RE = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/;

/**
 * Parse a Markdown document, splitting YAML frontmatter from the body.
 *
 * The frontmatter block is stripped manually with a regex before `marked` is
 * invoked, so that `marked` never sees the leading `---` delimiters (which it
 * would otherwise render as a literal horizontal rule).
 *
 * gray-matter is then used to parse the YAML payload itself.
 */
export function parseMarkdown(raw: string): ParsedDocument {
  const match = raw.match(FRONTMATTER_RE);

  let frontmatter: Frontmatter = {};
  let body = raw;

  if (match) {
    body = raw.slice(match[0].length);
    const parsed = matter(match[0]);
    frontmatter = (parsed.data ?? {}) as Frontmatter;
  }

  const html = marked.parse(body) as string;
  return { frontmatter, html, body };
}

import * as fs from 'fs';
import * as path from 'path';
import { parseMarkdown } from './markdown';

export interface Page {
  slug: string;
  title: string;
  date: string | null;
  tags: string[];
  html: string;
  sourcePath: string;
  outputPath: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export interface BuildResult {
  pages: Page[];
  outputDir: string;
  indexPath: string;
}

function collectMarkdownFiles(dir: string): string[] {
  const results: string[] = [];
  if (!fs.existsSync(dir)) {
    return results;
  }
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...collectMarkdownFiles(full));
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
      results.push(full);
    }
  }
  return results;
}

function toSlug(contentDir: string, filePath: string): string {
  const rel = path.relative(contentDir, filePath);
  const ext = path.extname(rel);
  const withoutExt = ext ? rel.slice(0, -ext.length) : rel;
  return withoutExt.split(path.sep).join('/');
}

function normalizeDate(value: unknown): string | null {
  if (value === null || value === undefined) {
    return null;
  }
  if (value instanceof Date) {
    return value.toISOString();
  }
  const str = String(value).trim();
  return str.length > 0 ? str : null;
}

function normalizeTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((v) => String(v).trim()).filter((v) => v.length > 0);
  }
  if (typeof value === 'string') {
    return value
      .split(',')
      .map((v) => v.trim())
      .filter((v) => v.length > 0);
  }
  return [];
}

export function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function relativeIndexLink(outputPath: string): string {
  const dir = path.dirname(outputPath);
  const rel = path.relative(dir, 'index.html');
  return rel.split(path.sep).join('/');
}

function renderPage(page: Page): string {
  const meta: string[] = [];
  if (page.date) {
    meta.push(
      `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>`
    );
  }
  if (page.tags.length > 0) {
    meta.push(
      `<ul class="tags">${page.tags
        .map((tag) => `<li>${escapeHtml(tag)}</li>`)
        .join('')}</ul>`
    );
  }

  const home = escapeHtml(relativeIndexLink(page.outputPath));

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(page.title)}</title>
</head>
<body>
<header><a href="${home}">Home</a></header>
<article>
<h1>${escapeHtml(page.title)}</h1>
${meta.join('\n')}
<div class="content">
${page.html}
</div>
</article>
</body>
</html>
`;
}

function renderIndex(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const date = page.date
        ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(
            page.date
          )}</time>`
        : '';
      const tags = page.tags.length
        ? ` <span class="tags">${page.tags
            .map((tag) => escapeHtml(tag))
            .join(', ')}</span>`
        : '';
      return `<li><a href="${escapeHtml(page.outputPath)}">${escapeHtml(
        page.title
      )}</a>${date}${tags}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Index</title>
</head>
<body>
<h1>Index</h1>
<ul>
${items}
</ul>
</body>
</html>
`;
}

export function build(options: BuildOptions): BuildResult {
  const { contentDir, outputDir } = options;

  const files = collectMarkdownFiles(contentDir);
  const pages: Page[] = files.map((file) => {
    const raw = fs.readFileSync(file, 'utf8');
    const { frontmatter, html } = parseMarkdown(raw);
    const slug = toSlug(contentDir, file);

    const rawTitle = frontmatter.title;
    const title =
      typeof rawTitle === 'string' && rawTitle.trim().length > 0
        ? rawTitle.trim()
        : slug;

    return {
      slug,
      title,
      date: normalizeDate(frontmatter.date),
      tags: normalizeTags(frontmatter.tags),
      html,
      sourcePath: file,
      outputPath: `${slug}.html`,
    };
  });

  pages.sort((a, b) => {
    const aDate = a.date;
    const bDate = b.date;
    if (!aDate && !bDate) {
      return a.title.localeCompare(b.title);
    }
    if (!aDate) {
      return 1;
    }
    if (!bDate) {
      return -1;
    }
    return bDate.localeCompare(aDate);
  });

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    const outFile = path.join(outputDir, page.outputPath);
    fs.mkdirSync(path.dirname(outFile), { recursive: true });
    fs.writeFileSync(outFile, renderPage(page));
  }

  const indexPath = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexPath, renderIndex(pages));

  return { pages, outputDir, indexPath };
}

import { build } from './builder';

export interface CliOptions {
  command: string;
  content: string;
  output: string;
}

export function parseArgs(argv: string[]): CliOptions {
  const options: CliOptions = {
    command: '',
    content: './content',
    output: './dist',
  };

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];

    if (arg === 'build') {
      options.command = 'build';
      i += 1;
    } else if (arg === '--content' || arg === '-c') {
      if (i + 1 < argv.length) {
        options.content = argv[i + 1];
        i += 2;
      } else {
        i += 1;
      }
    } else if (arg.startsWith('--content=')) {
      options.content = arg.slice('--content='.length);
      i += 1;
    } else if (arg === '--output' || arg === '-o') {
      if (i + 1 < argv.length) {
        options.output = argv[i + 1];
        i += 2;
      } else {
        i += 1;
      }
    } else if (arg.startsWith('--output=')) {
      options.output = arg.slice('--output='.length);
      i += 1;
    } else if (arg === '--help' || arg === '-h') {
      options.command = 'help';
      i += 1;
    } else {
      i += 1;
    }
  }

  return options;
}

function printHelp(): void {
  const text = `Usage: ssg build [options]

Build a static site from a directory of Markdown files.

Options:
  --content <dir>   Directory containing Markdown files (default: ./content)
  --output <dir>    Directory to write generated HTML (default: ./dist)
  -h, --help        Show this help message
`;
  process.stdout.write(text);
}

export function runCli(argv: string[]): number {
  const options = parseArgs(argv);

  if (options.command === 'help') {
    printHelp();
    return 0;
  }

  if (options.command === '') {
    printHelp();
    return 1;
  }

  if (options.command !== 'build') {
    process.stderr.write(`Unknown command: ${options.command}\n`);
    printHelp();
    return 1;
  }

  const result = build({
    contentDir: options.content,
    outputDir: options.output,
  });

  process.stdout.write(
    `Built ${result.pages.length} page(s) to ${result.outputDir}\n`
  );
  return 0;
}

#!/usr/bin/env node
import { runCli } from './cli';

export { parseMarkdown, Frontmatter, ParsedDocument } from './markdown';
export {
  build,
  escapeHtml,
  Page,
  BuildOptions,
  BuildResult,
} from './builder';
export { parseArgs, runCli, CliOptions } from './cli';

if (require.main === module) {
  process.exitCode = runCli(process.argv.slice(2));
}

import { parseMarkdown } from '../src/markdown';

describe('parseMarkdown', () => {
  it('parses YAML frontmatter with title, date and tags', () => {
    const md = `---
title: Hello World
date: 2024-01-15
tags:
  - typescript
  - ssg
---
# Heading

Some body text.
`;
    const { frontmatter, html, body } = parseMarkdown(md);

    expect(frontmatter.title).toBe('Hello World');
    expect(frontmatter.date).toEqual('2024-01-15');
    expect(frontmatter.tags).toEqual(['typescript', 'ssg']);
    expect(html).toContain('<h1>Heading</h1>');
    expect(html).toContain('Some body text.');
    expect(body).not.toContain('---');
  });

  it('supports comma-separated tags as a string', () => {
    const md = `---
title: Post
tags: a, b, c
---
Text`;
    const { frontmatter } = parseMarkdown(md);
    expect(frontmatter.tags).toBe('a, b, c');
  });

  it('handles documents without frontmatter', () => {
    const md = `# No Frontmatter

Just content.`;
    const { frontmatter, html } = parseMarkdown(md);

    expect(frontmatter).toEqual({});
    expect(html).toContain('<h1>No Frontmatter</h1>');
    expect(html).toContain('Just content.');
  });

  it('does not render the frontmatter delimiter as a horizontal rule', () => {
    const md = `---
title: No Hr
---
# Content`;
    const { html } = parseMarkdown(md);
    expect(html).not.toContain('<hr');
  });

  it('renders inline markdown such as links and emphasis', () => {
    const md = `---
title: Inline
---
Read the [docs](https://example.com) *now*.`;
    const { html } = parseMarkdown(md);
    expect(html).toContain('<a href="https://example.com">docs</a>');
    expect(html).toContain('<em>now</em>');
  });

  it('strips CRLF frontmatter delimiters', () => {
    const md = '---\r\ntitle: Windows\r\n---\r\n# Body';
    const { html, body } = parseMarkdown(md);
    expect(body).not.toContain('---');
    expect(html).toContain('<h1>Body</h1>');
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { build } from '../src/builder';

function tmpdir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
}

describe('build', () => {
  it('generates index.html and one HTML file per page', () => {
    const root = tmpdir();
    const content = path.join(root, 'content');
    const output = path.join(root, 'dist');
    fs.mkdirSync(content, { recursive: true });
    fs.writeFileSync(
      path.join(content, 'hello.md'),
      `---
title: Hello
date: 2024-02-01
tags: [greeting]
---
# Hello world
`
    );
    fs.writeFileSync(
      path.join(content, 'second.md'),
      `---
title: Second Post
---
Body two
`
    );

    const result = build({ contentDir: content, outputDir: output });

    expect(result.pages).toHaveLength(2);
    expect(fs.existsSync(path.join(output, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(output, 'hello.html'))).toBe(true);
    expect(fs.existsSync(path.join(output, 'second.html'))).toBe(true);
  });

  it('lists all pages with links in index.html', () => {
    const root = tmpdir();
    const content = path.join(root, 'content');
    const output = path.join(root, 'dist');
    fs.mkdirSync(content, { recursive: true });
    fs.writeFileSync(
      path.join(content, 'alpha.md'),
      '---\ntitle: Alpha\n---\n# A\n'
    );
    fs.writeFileSync(
      path.join(content, 'beta.md'),
      '---\ntitle: Beta\n---\n# B\n'
    );

    build({ contentDir: content, outputDir: output });

    const index = fs.readFileSync(path.join(output, 'index.html'), 'utf8');
    expect(index).toContain('href="alpha.html"');
    expect(index).toContain('href="beta.html"');
    expect(index).toContain('Alpha');
    expect(index).toContain('Beta');
  });

  it('renders markdown body and frontmatter title into page HTML', () => {
    const root = tmpdir();
    const content = path.join(root, 'content');
    const output = path.join(root, 'dist');
    fs.mkdirSync(content, { recursive: true });
    fs.writeFileSync(
      path.join(content, 'post.md'),
      '---\ntitle: My Title\n---\n## Section\n\nHello *there*.\n'
    );

    build({ contentDir: content, outputDir: output });

    const page = fs.readFileSync(path.join(output, 'post.html'), 'utf8');
    expect(page).toContain('<title>My Title</title>');
    expect(page).toContain('<h1>My Title</h1>');
    expect(page).toContain('<h2>Section</h2>');
    expect(page).toContain('<em>there</em>');
    expect(page).not.toContain('---');
  });

  it('recurses into subdirectories and nests output paths', () => {
    const root = tmpdir();
    const content = path.join(root, 'content');
    const output = path.join(root, 'dist');
    const nested = path.join(content, 'blog', '2024');
    fs.mkdirSync(nested, { recursive: true });
    fs.writeFileSync(
      path.join(nested, 'post.md'),
      '---\ntitle: Nested\n---\n# Nested\n'
    );

    build({ contentDir: content, outputDir: output });

    expect(fs.existsSync(path.join(output, 'blog', '2024', 'post.html'))).toBe(
      true
    );
  });

  it('falls back to the slug as title when frontmatter has no title', () => {
    const root = tmpdir();
    const content = path.join(root, 'content');
    const output = path.join(root, 'dist');
    fs.mkdirSync(content, { recursive: true });
    fs.writeFileSync(path.join(content, 'untitled.md'), '# Heading only\n');

    const result = build({ contentDir: content, outputDir: output });

    expect(result.pages[0].title).toBe('untitled');
    const index = fs.readFileSync(path.join(output, 'index.html'), 'utf8');
    expect(index).toContain('untitled');
  });

  it('produces an empty index when no markdown files exist', () => {
    const root = tmpdir();
    const content = path.join(root, 'content');
    const output = path.join(root, 'dist');
    fs.mkdirSync(content, { recursive: true });

    const result = build({ contentDir: content, outputDir: output });

    expect(result.pages).toHaveLength(0);
    expect(fs.existsSync(path.join(output, 'index.html'))).toBe(true);
  });

  it('escapes HTML in titles and tag names', () => {
    const root = tmpdir();
    const content = path.join(root, 'content');
    const output = path.join(root, 'dist');
    fs.mkdirSync(content, { recursive: true });
    fs.writeFileSync(
      path.join(content, 'xss.md'),
      '---\ntitle: <script>alert(1)</script>\ntags: [<img>]\n---\nBody\n'
    );

    build({ contentDir: content, outputDir: output });

    const index = fs.readFileSync(path.join(output, 'index.html'), 'utf8');
    expect(index).toContain('&lt;script&gt;');
    expect(index).not.toContain('<script>alert(1)</script>');
